setup:
MUTATE {
  CREATE CONCEPT ?hammer { TYPE "Tool" NAME "Hammer" }
  CREATE CONCEPT ?shed { TYPE "Room" NAME "Shed" }
}

cases.command:
MUTATE {
  ENSURE PROPOSITION ?a (:tool, "labelled", :room)
  ENSURE PROPOSITION ?b (:tool, "labelled", "the good one")
}

MUTATE {
  CREATE CONCEPT ?chisel { TYPE "Tool" NAME "Chisel" }
  CREATE CONCEPT ?loft { TYPE "Room" NAME "Loft" }
  ENSURE PROPOSITION ?p (?chisel, "kept_in", ?loft)
}

MUTATE {
  CREATE CONCEPT ?bench { TYPE "Tool" NAME "Bench" }
  ENSURE PROPOSITION ?p (:tool, "kept_in", ?bench)
}

MUTATE {
  CREATE EVIDENCE ?e {
    SET FIELDS {evidence_class: "observation", payload: "the handle is splitting"}
    SET FACET "Wear" {level: 0.4}
  }
}

MUTATE {
  CREATE CONCEPT ?saw { TYPE "Tool" NAME "Saw" }
  CREATE CONCEPT ?plane { TYPE "Tool" NAME "Plane" }
  UPDATE ?saw SET STRUCTURAL { ("kept_with", ?plane) }
}

MUTATE {
  CREATE CONCEPT ?awl {
    TYPE "Tool"
    NAME "Awl"
    SET STRUCTURAL {
      ("kept_with", :tool)
      ("kept_with", :tool)
    }
  }
}

MUTATE {
  CREATE CONCEPT ?rasp { TYPE "Tool" NAME "Rasp" }
  CREATE CONCEPT ?file { TYPE "Tool" NAME "File" }
  CREATE CONCEPT ?vice {
    TYPE "Tool"
    NAME "Vice"
    SET STRUCTURAL {
      ("kept_with", :tool)
      ("kept_with", ?rasp)
      ("kept_with", ?file)
    }
  }
}
